from pathlib import Path
def load_config(config_dir, name):
    config_path = Path(config_dir) / f'{name}.json'
    return config_path.read_text()

def get_completion(client, model_name, prompt):
    response = client.chat.completions.create(
        model=model_name,
        messages=[{'role': 'user', 'content': prompt}],
    )
    return response.choices[0].message.content.strip()

def score_response(judge_client, question, answer):
    result = judge_client.run([{'question': question, 'answer': answer}])[0]
    return round(result, 2)

def embed_text(client, text):
    response = client.embeddings.create(model='text-embedding-3-small', input=text)
    return response.data[0].embedding

def classify_sentiment(client, text):
    resp = client.chat.completions.create(
        model='gpt-4',
        messages=[{'role': 'system', 'content': 'Classify sentiment.'}, {'role': 'user', 'content': text}],
    )
    return resp.choices[0].message.content

def evaluate_batch(model, eval_set, metric_fn):
    scores = [metric_fn(x, y) for x, y in eval_set]
    return sum(scores) / len(scores)

def run_pipeline(pipeline, input_data):
    result = pipeline.run(input_data)
    return result.output

